package be.cap.backend.accounts;

import java.security.Principal;
import java.time.*;
import java.util.*;
import org.springframework.context.annotation.Profile;
import org.springframework.http.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import tools.jackson.databind.json.JsonMapper;

/** An assigned snapshot is separate from the coach's editable draft and its saved revisions. */
@RestController @Profile("accounts") @RequestMapping("/api/meal-plans") @Transactional
public class MealPlanSchedule {
    public record Assign(UUID id,int version,LocalDate startDate,LocalDate endDate,boolean replaceExisting){}
    public record Assignment(UUID id,UUID planId,UUID athleteId,LocalDate startDate,LocalDate endDate,String name,String assignedAt){}
    public record Revision(UUID planId,int version,LocalDate weekStart,MealPlanController.Content content,String savedAt){}
    public record DayView(UUID assignmentId,UUID planId,LocalDate date,String name,LocalDate startDate,LocalDate endDate,List<MealPlanController.Meal> meals,Map<Integer,Boolean> consumed){}
    public record Consume(LocalDate date,int meal,String diaryMeal,UUID assignmentId,UUID planId){}
    private final JdbcTemplate jdbc;private final AccountService accounts;private final StaffPolicy policy;private final MealPlanController plans;private final FoodDiaryController diary;
    private final JsonMapper json=JsonMapper.builder().build();
    public MealPlanSchedule(JdbcTemplate jdbc,AccountService accounts,StaffPolicy policy,MealPlanController plans,FoodDiaryController diary){this.jdbc=jdbc;this.accounts=accounts;this.policy=policy;this.plans=plans;this.diary=diary;}
    private ResponseStatusException error(HttpStatus code,String message){return new ResponseStatusException(code,message);}
    private AccountService.Account coach(Principal p,UUID client){var actor=accounts.account(p.getName());policy.require(actor,StaffPolicy.Permission.NUTRITION_MANAGE);policy.requireClient(actor,client.toString());return actor;}
    private void date(LocalDate value){if(value==null||value.getYear()<2000||value.getYear()>2100)throw error(HttpStatus.BAD_REQUEST,"Kies een geldige datum.");}
    @GetMapping("/history") public List<Revision> history(Principal p,@RequestParam UUID athleteId,@RequestParam(defaultValue="0") int offset){coach(p,athleteId);if(offset<0||offset>10000)throw error(HttpStatus.BAD_REQUEST,"Ongeldige pagina.");return jdbc.query("SELECT * FROM meal_plan_revision WHERE athlete_id=? ORDER BY saved_at DESC,version DESC LIMIT 20 OFFSET ?",(r,i)->new Revision(r.getObject("plan_id",UUID.class),r.getInt("version"),r.getDate("week_start").toLocalDate(),json.readValue(r.getString("payload"),MealPlanController.Content.class),r.getTimestamp("saved_at").toInstant().toString()),athleteId,offset);}
    @GetMapping("/assignments") public List<Assignment> assignments(Principal p,@RequestParam UUID athleteId){coach(p,athleteId);return jdbc.query("SELECT * FROM meal_plan_assignment WHERE athlete_id=? ORDER BY start_date DESC LIMIT 100",(r,i)->new Assignment(r.getObject("id",UUID.class),r.getObject("plan_id",UUID.class),athleteId,r.getDate("start_date").toLocalDate(),r.getDate("end_date").toLocalDate(),json.readValue(r.getString("payload"),MealPlanController.Content.class).name(),r.getTimestamp("assigned_at").toInstant().toString()),athleteId);}
    @PostMapping("/{id}/assignments") public Assignment assign(Principal p,@PathVariable UUID id,@RequestBody Assign input){
        if(input==null||input.id()==null)throw error(HttpStatus.BAD_REQUEST,"Toewijzingsreferentie ontbreekt.");date(input.startDate());date(input.endDate());if(input.endDate().isBefore(input.startDate())||input.endDate().isAfter(input.startDate().plusDays(365)))throw error(HttpStatus.BAD_REQUEST,"Kies een einddatum op of na de startdatum, maximaal één jaar later.");
        var rows=jdbc.queryForList("SELECT * FROM meal_plan WHERE id=?",id);if(rows.isEmpty()||rows.getFirst().get("athlete_id")==null)throw error(HttpStatus.NOT_FOUND,"Klantenschema niet gevonden.");var row=rows.getFirst();UUID client=(UUID)row.get("athlete_id");var actor=coach(p,client);
        jdbc.query("SELECT id FROM cap_user WHERE id=? FOR UPDATE",(r,i)->r.getObject(1),client);
        var previous=jdbc.queryForList("SELECT * FROM meal_plan_assignment WHERE id=?",input.id());if(!previous.isEmpty()){var old=previous.getFirst();if(!client.equals(old.get("athlete_id"))||!id.equals(old.get("plan_id"))||!input.startDate().equals(((java.sql.Date)old.get("start_date")).toLocalDate())||!input.endDate().equals(((java.sql.Date)old.get("end_date")).toLocalDate()))throw error(HttpStatus.CONFLICT,"Deze toewijzingsreferentie is al gebruikt.");return assignments(p,client).stream().filter(a->a.id().equals(input.id())).findFirst().orElseThrow();}
        row=jdbc.queryForList("SELECT * FROM meal_plan WHERE id=? FOR UPDATE",id).getFirst();if(((Number)row.get("version")).intValue()!=input.version())throw error(HttpStatus.CONFLICT,"Het schema is gewijzigd. Laad de opgeslagen versie opnieuw.");var content=json.readValue(row.get("payload").toString(),MealPlanController.Content.class);if(content.days().stream().allMatch(d->d.meals().isEmpty()))throw error(HttpStatus.BAD_REQUEST,"Voeg eerst maaltijden toe en bewaar het schema.");
        boolean overlap=jdbc.queryForObject("SELECT COUNT(*) FROM meal_plan_assignment WHERE athlete_id=? AND start_date<=? AND end_date>=?",Integer.class,client,input.endDate(),input.startDate())>0;
        if(overlap&&!input.replaceExisting())throw error(HttpStatus.CONFLICT,"Er staat al een schema op een van deze datums. Bevestig dat dit schema voor die dagen voorrang krijgt.");
        jdbc.update("INSERT INTO meal_plan_assignment(id,plan_id,athlete_id,start_date,end_date,payload,assigned_by) VALUES(?,?,?,?,?,?,?)",input.id(),id,client,input.startDate(),input.endDate(),json.writeValueAsString(content),actor.id());policy.audit(actor,"MEAL_PLAN_ASSIGN",id.toString(),"Assigned snapshot for "+input.startDate()+" to "+input.endDate());return assignments(p,client).stream().filter(a->a.id().equals(input.id())).findFirst().orElseThrow();
    }
    private UUID entryId(UUID athlete,DayView view,int meal){return UUID.nameUUIDFromBytes(("cap-assigned-meal:"+athlete+":"+view.assignmentId()+":"+view.date()+":"+meal).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    private DayView day(UUID athlete,LocalDate date){date(date);var rows=jdbc.queryForList("SELECT * FROM meal_plan_assignment WHERE athlete_id=? AND start_date<=? AND end_date>=? ORDER BY assigned_at DESC,id DESC LIMIT 1",athlete,date,date);int weekday=date.getDayOfWeek().getValue()-1;
        if(rows.isEmpty()){var legacy=plans.ownPublished(athlete,date.with(DayOfWeek.MONDAY));if(legacy.isEmpty())return new DayView(null,null,date,"",null,null,List.of(),Map.of());var plan=legacy.getFirst();return new DayView(null,plan.id(),date,plan.content().name(),plan.weekStart(),plan.weekStart().plusDays(6),plan.content().days().get(weekday).meals(),Map.of());}
        var row=rows.getFirst();var content=json.readValue(row.get("payload").toString(),MealPlanController.Content.class);UUID assignment=(UUID)row.get("id");var meals=content.days().stream().filter(d->d.day()==weekday).findFirst().orElseThrow().meals();var view=new DayView(assignment,(UUID)row.get("plan_id"),date,content.name(),((java.sql.Date)row.get("start_date")).toLocalDate(),((java.sql.Date)row.get("end_date")).toLocalDate(),meals,Map.of());var consumed=new LinkedHashMap<Integer,Boolean>();for(int i=0;i<meals.size();i++)consumed.put(i,jdbc.queryForObject("SELECT COUNT(*) FROM food_diary_entry WHERE athlete_id=? AND id=?",Integer.class,athlete,entryId(athlete,view,i))>0);return new DayView(view.assignmentId(),view.planId(),date,view.name(),view.startDate(),view.endDate(),meals,consumed);
    }
    @GetMapping("/self/day") public ResponseEntity<DayView> self(Principal p,@RequestParam LocalDate date){var actor=accounts.account(p.getName());if(!actor.role().equals("ATHLETE"))throw error(HttpStatus.FORBIDDEN,"Alleen klanten hebben een eigen toegewezen schema.");return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(day(actor.id(),date));}
    @PostMapping("/self/day/consume") public FoodDiaryController.Entry consume(Principal p,@RequestBody Consume input){var actor=accounts.account(p.getName());if(!actor.role().equals("ATHLETE"))throw error(HttpStatus.FORBIDDEN,"Alleen klanten kunnen een maaltijd registreren.");if(input==null)throw error(HttpStatus.BAD_REQUEST,"Kies een maaltijd.");date(input.date());if(input.date().isAfter(LocalDate.now(ZoneId.of("Europe/Brussels")))||input.meal()<0||!Set.of("breakfast","lunch","dinner","snack","bedtime","pre","post").contains(Objects.toString(input.diaryMeal(),"")))throw error(HttpStatus.BAD_REQUEST,"Controleer datum en maaltijd.");jdbc.query("SELECT id FROM cap_user WHERE id=? FOR UPDATE",(r,i)->r.getObject(1),actor.id());var view=day(actor.id(),input.date());if(!Objects.equals(input.assignmentId(),view.assignmentId())||!Objects.equals(input.planId(),view.planId())||input.meal()>=view.meals().size())throw error(HttpStatus.CONFLICT,"Het toegewezen schema is gewijzigd. Laad de dag opnieuw.");
        if(view.assignmentId()==null)return plans.consume(p,view.planId(),new MealPlanController.ConsumeInput(input.date().getDayOfWeek().getValue()-1,input.meal(),input.diaryMeal())).getBody();
        UUID id=entryId(actor.id(),view,input.meal());var previous=jdbc.query("SELECT payload FROM food_diary_entry WHERE id=? AND athlete_id=?",(r,i)->json.readValue(r.getString(1),FoodDiaryController.Entry.class),id,actor.id());if(!previous.isEmpty())return previous.getFirst();var meal=view.meals().get(input.meal());var total=NutritionPlanValidator.totals(List.of(meal));var ingredients=meal.foods().stream().map(f->{double factor=f.amount()/(f.unit().equals("stuk")?1:100);return new FoodDiaryController.Ingredient(f.name(),null,f.amount(),f.unit(),f.calories()*factor,f.proteinG()*factor,f.carbsG()*factor,f.fatG()*factor);}).toList();return diary.add(p,new FoodDiaryController.Entry(id,input.date(),input.diaryMeal(),meal.name(),"assigned-plan:"+view.assignmentId(),1.0,"maaltijd",total.calories(),total.proteinG(),total.carbsG(),total.fatG(),ingredients)).getBody();
    }
}
